#include <cstdio>
#include <algorithm>
#include <climits>
using namespace std;

int n, k;
long long vi[200005];
long long mem[200005];
bool vis[200005];

long long solve(int indx) {
    if (indx == n - 1) return 0;
    if (vis[indx]) return mem[indx];
    vis[indx] = true;
    mem[indx] = LLONG_MAX;
    for (int i = indx + 1; i <= min(indx + k, n - 1); i++) {
        mem[indx] = min(mem[indx], solve(i) + abs(vi[indx] - vi[i]));
    }
    return mem[indx];
}

int main() {
    scanf("%d%d", &n, &k);
    for (int i = 0; i < n; i++) {
        scanf("%lld", &vi[i]);
    }
    printf("%lld\n", solve(0));
    return 0;
}

